# Fetch liked songs across all pages
spotify_token = spotify_login['access_token']

liked_songs = {}  # song_id -> song dict
page_index = 0
page_limit = 20
while True:
    resp = apis.spotify.show_liked_songs(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    print('liked_page', page_index, 'resp_type', type(resp), 'len', len(resp) if isinstance(resp, list) else (len(resp.get('songs',[])) if isinstance(resp, dict) else None))
    if isinstance(resp, dict) and 'songs' in resp:
        songs = resp['songs']
    else:
        songs = resp
    if not songs:
        break
    for s in songs:
        liked_songs[s['song_id']] = s
    if isinstance(resp, list) and len(songs) < page_limit:
        break
    if isinstance(resp, dict):
        if len(songs) < page_limit:
            break
    page_index += 1

print('liked_total', len(liked_songs))
# print a sample
sample_ids = list(liked_songs.keys())[:5]
print('liked_sample', [(sid, liked_songs[sid]['title']) for sid in sample_ids])

# Fetch album library song_ids across all pages
album_song_ids = set()
page_index = 0
page_limit = 20
while True:
    resp = apis.spotify.show_album_library(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    print('album_lib_page', page_index, 'len', len(resp) if isinstance(resp, list) else (len(resp.get('albums',[])) if isinstance(resp, dict) else 'other'))
    if isinstance(resp, dict) and 'albums' in resp:
        albums = resp['albums']
    else:
        albums = resp
    if not albums:
        break
    for a in albums:
        for sid in a.get('song_ids', []) or []:
            album_song_ids.add(sid)
    if isinstance(resp, list) and len(albums) < page_limit:
        break
    if isinstance(resp, dict):
        if len(albums) < page_limit:
            break
    page_index += 1

print('album_song_ids_count', len(album_song_ids))
print('album_song_ids_sample', list(sorted(album_song_ids))[:10])

